        article_form = ArticleForm(
            instance=Article(title='Test Article', category=self.c1),
            data={'title': 'Test Article', 'category': self.c2.pk},
            meta={'limit_choices_to': q_obj}
        )
        self.assertTrue(article_form.is_valid())

        # Test case 3: limit_choices_to is a callable
        def limit_choices():
            return Q(slug__icontains='test')

        article_form = ArticleForm(
            instance=Article(title='Test Article', category=self.c1),
            data={'title': 'Test Article', 'category': self.c2.pk},
            meta={'limit_choices_to': limit_choices}
        )
