class TestPyobjMixinGetmodpath(object):
    def test_getmodpath_simple(self, testdir):
        testdir.makepyfile(
            """
            import pytest

            @pytest.fixture
            def arg():
                return 1

            def test_func(arg):
                pass
            """
        )
        items, _ = testdir.inline_genitems()
        module_item = items[0]
        assert module_item.getmodpath() == "test_func"

    def test_getmodpath_with_package(self, testdir):
        root = testdir.mkdir("root")
        root.join("__init__.py").write("")
        sub = root.mkdir("sub")
        sub.ensure("__init__.py")
        sub.join("test_func.py").write(
            """
            import pytest

            @pytest.fixture
            def arg():
                return 1

            def test_func(arg):
                pass
            """
        )
        testdir.syspathinsert(root.pure_path)
        items, _ = testdir.inline_genitems()
        module_item = items[0]
        assert module_item.getmodpath() == "sub.test_func"

    def test_getmodpath_with_class(self, testdir):
        testdir.makepyfile(
            """
            import pytest

            @pytest.fixture
            def arg():
                return 1

            class TestClass:
                def test_func(self, arg):
                    pass
            """
        )
        items, _ = testdir.inline_genitems()
        module_item = items[0]
        assert module_item.getmodpath() == "TestClass.test_func"

    def test_getmodpath_with_init(self, testdir):
        root = testdir.mkdir("root")
        root.join("__init__.py").write("")
        sub = root.mkdir("sub")
        sub.ensure("__init__.py")
        sub.join("test_func.py").write(
            """
