def test_mathematica_parser_compile_dictionary():
    from sympy.parsing.mathematica import MathematicaParser
    import sympy

    parser = MathematicaParser()

    # Test case 1: Empty dictionary
    dic = {}
    d = parser._compile_dictionary(dic)
    assert d == {}

    # Test case 2: Simple correspondence
    dic = {'Sqrt[x]': 'sqrt(x)'}
    d = parser._compile_dictionary(dic)
    assert d == {('Sqrt', 1): {'fs': 'sqrt(x)', 'args': ['x'], 'pat': re.compile(r'(?:(?<=[^a-zA-Z])\s*)Sqrt\(\s*([a-zA-Z\d_]+)\s*\)(?:(?=\s*)|$)', re.VERBOSE)}}

    # Test case 3: Multiple correspondences
    dic = {
        'Sqrt[x]': 'sqrt(x)',
        'Exp[x]': 'exp(x)'
    }
    d = parser._compile_dictionary(dic)
    assert len(d) == 2
    assert ('Sqrt', 1) in d
    assert ('Exp', 1) in d

    # Test case 4: Correspondence with arguments
    dic = {'Sin[x, y]': 'sin(x, y)'}
    d = parser._compile_dictionary(dic)
    assert d == {('Sin', 2): {'fs': 'sin(x, y)', 'args': ['x', 'y'], 'pat': re.compile(r'(?:(?<=[^a-zA-Z])\s*)Sin\(\s*([a-zA-Z\d_]+)\s*,\s*([a-zA-Z\d_]+)\s*\)(?:(?=\s*)|$)', re.VERBOSE)}}

    # Test case 5: Correspondence with variable-length arguments
    dic = {'F[x, *args]': 'F(x, *args)'}
    d = parser._compile_dictionary(dic)
    assert d == {('F', '*'): {'fs': 'F(x, *args)', 'args': ['x', '*'], 'pat': re.compile(r'(?:(?<=[^a-zA-Z])\s*)F\(\s*([a-zA-Z\d_]+)\s*,\s*([a-zA-Z\d_]+)\s*\)(?:(?=\s*)|$)', re.VERBOSE)}}

    # Test case 6: Invalid function form
    dic = {'Sqrt[x': 'sqrt(x)'}
    with raises(ValueError) as excinfo:
        parser._compile_dictionary(dic)
    assert "function form is invalid" in str(excinfo.value)

    # Test case 7: Invalid bracket
    dic = {'Sqrt[x': 'sqrt(x)'}
    with raises(ValueError) as excinfo:
        parser._compile_dictionary(dic)
    assert "function form is invalid" in str(excinfo.value)

    # Test case 8: Check for Pi
    dic = {'Pi': 'pi'}
    d = parser._compile_dictionary(dic)
    assert d == {('Pi', 1): {'fs': 'pi', 'args': [], 'pat': re.compile(r'(?:(?<=[^a-zA-Z])\s*)Pi(?:(?=\s*)|$)', re.VERBOSE)}}
