            self.assertEqual(arg, 1)

        _call_with_optional_argument(func, 1)

    def test_function_does_not_accept_arguments(self):
        def func():
            pass

        _call_with_optional_argument(func, None)

    def test_function_is_method(self):
        class TestClass:
            def method(self, arg):
                self.assertEqual(arg, 1)

        instance = TestClass()
        _call_with_optional_argument(instance.method, 1)

    def test_function_is_staticmethod(self):
        class TestClass:
            @staticmethod
            def method(arg):
                self.assertEqual(arg, 1)

        _call_with_optional_argument(TestClass.method, 1)

    def test_function_with_default_argument(self):
        def func(arg=2):
            self.assertEqual(arg, 2)

        _call_with_optional_argument(func, None)

    def test_function_with_keyword_argument(self):
        def func(arg="hello"):
            self.assertEqual(arg, "hello")

        _call_with_optional_argument(func, None)

    def test_function_with_multiple_arguments(self):
        def func(arg1, arg2):
            self.assertEqual(arg1, 1)
            self.assertEqual(arg2, 2)

        _call_with_optional_argument(func, 1)

    def test_function_with_optional_argument_and_multiple_arguments(self):
        def func(arg1, arg2=3):
            self.assertEqual(arg1, 1)
            self.assertEqual(arg2, 3)

        _call_with_optional_argument(func, 1)

    def test_function_with_optional_argument_and_multiple_arguments_with_value(self):
        def func(arg1, arg2=3):
            self.assertEqual(arg1, 1)
            self.assertEqual(arg2, 4)

        _call_with_optional_argument(func, 1, arg2=4)
