        assert item.callspec.id == "1"
        assert item.callspec.params == {"arg": 1}
        assert item.keywords == {"arg": 1}

    def test_init_without_callspec(self, pytester: Pytester) -> None:
        """Test Function.__init__ without a callspec."""
        p = pytester.makepyfile(
            """
            def test_func():
                assert True
            """
        )
        item = pytester.getitem(p, "test_func")
        assert item.callspec is None
        assert item.keywords == {}

    def test_init_with_keywords(self, pytester: Pytester) -> None:
        """Test Function.__init__ with keywords."""
        p = pytester.makepyfile(
            """
