from django.test import TestCase
from admin_inlines.admin import InlineModelAdmin
from admin_inlines.models import Author, Book

class TestInlineModelAdminInit(TestCase):

    def test_formfield_overrides_merge(self):
        """
        Test that formfield_overrides are correctly merged with defaults.
        """
        class MyInlineModelAdmin(InlineModelAdmin):
            pass

        model_admin = MyInlineModelAdmin(Author, None)

        # Add a custom formfield override
        model_admin.formfield_overrides = {
            Book: {'widget': 'custom_widget'}
        }

        # Check that the merged formfield_overrides contain both the default
        # and the custom override.
        expected_overrides = {
            Book: {'widget': 'custom_widget'},
            **InlineModelAdmin.FORMFIELD_FOR_DBFIELD_DEFAULTS.get(Book, {})
        }

        self.assertEqual(model_admin.formfield_overrides, expected_overrides)

    def test_formfield_overrides_no_merge_if_already_defined(self):
        """
        Test that formfield_overrides are not overwritten if already defined.
        """
        class MyInlineModelAdmin(InlineModelAdmin):
            pass

        model_admin = MyInlineModelAdmin(Author, None)

        # Add a custom formfield override
        model_admin.formfield_overrides = {
            Book: {'widget': 'custom_widget'}
        }

        # Add another custom formfield override
        model_admin.formfield_overrides = {
            Book: {'widget': 'another_widget'}
        }

        # Check that the formfield_overrides contain only the last override.
        self.assertEqual(model_admin.formfield_overrides[Book]['widget'], 'another_widget')
