from django.db import models
from django.test import TestCase, skipUnlessDBFeature
from django.core.checks import Error

@skipUnlessDBFeature('supports_table_check_constraints')
class SaveParentsTests(TestCase):
    def test_save_parents_with_unique_constraint(self):
        class Parent(models.Model):
            name = models.CharField(max_length=100, unique=True)

        class Child(Parent):
            pass

        parent = Parent.objects.create(name="Parent Name")
        child = Child.objects.create(name="Child Name")

        # Save the child, which should trigger the save_parents method
        child.save()

        self.assertTrue(Parent.objects.filter(name="Child Name").exists())

    def test_save_parents_with_check_constraint(self):
        class Parent(models.Model):
            value = models.IntegerField(
                constraints=[
                    models.CheckConstraint(check=models.Q(value__gt=0), name="positive_value")
                ]
            )

        class Child(Parent):
            pass

        parent = Parent.objects.create(value=10)
        child = Child.objects.create(value=20)

        child.save()

        self.assertTrue(Parent.objects.filter(value=20).exists())

    def test_save_parents_with_multiple_parents(self):
        class GrandParent(models.Model):
            grandparent_field = models.CharField(max_length=100)

        class Parent(GrandParent):
            parent_field = models.CharField(max_length=100)

        class Child(Parent):
            child_field = models.CharField(max_length=100)

        grandparent = GrandParent.objects.create(grandparent_field="Grandparent Value")
        parent = Parent.objects.create(parent_field="Parent Value", grandparent=grandparent)
        child = Child.objects.create(child_field="Child Value", parent=parent)

        child.save()

        self.assertTrue(Parent.objects.filter(parent_field="Child Value").exists())
        self.assertTrue(GrandParent.objects.filter(grandparent_field="Grandparent Value").exists())

    def test_save_parents_with_one_to_one_field(self):
        class Parent(models.Model):
            name = models.CharField(max_length=100)

        class Child(Parent):
            parent = models.OneToOneField(Parent, on_delete=models.CASCADE)

        parent = Parent.objects.create(name="Parent Name")
        child = Child.objects.create(parent=parent)

        child.save()

        self.assertTrue(Parent.objects.filter(name="Parent Name").exists())
        self.assertTrue(Child.objects.filter(parent=parent).exists())

    def test_save_parents_with_existing_parent(self):
        class Parent(models.Model):
            name = models.CharField(max_length=100)

        class Child(Parent):
            pass

        parent = Parent.objects.create(name="Existing Parent")
        child = Child.objects.create(name="Child Name", parent=parent)

        child.save()

        self.assertTrue(Parent.objects.filter(name="Existing Parent").exists())
        self.assertTrue(Child.objects.filter(name="Child Name").exists())
