def test_closest_points_edge_cases():
    # Test with only one point
    raises(ValueError, lambda: closest_points(Point2D(0, 0)))

    # Test with two identical points
    assert closest_points(Point2D(0, 0), Point2D(0, 0)) == {(Point2D(0, 0), Point2D(0, 0))}

    # Test with collinear points
    points = [Point2D(0, 0), Point2D(1, 0), Point2D(2, 0)]
    assert closest_points(*points) == {(Point2D(0, 0), Point2D(1, 0)), (Point2D(1, 0), Point2D(2, 0))}

    # Test with points forming a square
    points = [Point2D(0, 0), Point2D(1, 0), Point2D(1, 1), Point2D(0, 1)]
    assert closest_points(*points) == {(Point2D(0, 0), Point2D(1, 0)), (Point2D(0, 0), Point2D(0, 1)), (Point2D(1, 0), Point2D(1, 1)), (Point2D(0, 1), Point2D(1, 1))}

    # Test with points forming a line
    points = [Point2D(0, 0), Point2D(1, 1), Point2D(2, 2), Point2D(3, 3)]
    assert closest_points(*points) == {(Point2D(0, 0), Point2D(1, 1)), (Point2D(1, 1), Point2D(2, 2)), (Point2D(2, 2), Point2D(3, 3))}

    # Test with a mix of close and far points
    points = [Point2D(0, 0), Point2D(1, 0), Point2D(5, 5), Point2D(6, 6)]
    assert closest_points(*points) == {(Point2D(0, 0), Point2D(1, 0))}

    # Test with points having same x coordinate
    points = [Point2D(1, 1), Point2D(1, 2), Point2D(1, 3)]
    assert closest_points(*points) == {(Point2D(1, 1), Point2D(1, 2)), (Point2D(1, 2), Point2D(1, 3))}

    # Test with points having same y coordinate
    points = [Point2D(1, 1), Point2D(2, 1), Point2D(3, 1)]
    assert closest_points(*points) == {(Point2D(1, 1), Point2D(2, 1)), (Point2D(2, 1), Point2D(3, 1))}
