    def test_check_with_custom_error_handlers(self):
        """
        Test URLResolver.check() with custom error handlers.
        """
        # Mock URLConf with custom error handlers
        class MockURLConf:
            def handler400(self, request, exception):
                return HttpResponsePermanentRedirect('/custom-400/')

            def handler403(self, request, exception):
                return HttpResponsePermanentRedirect('/custom-403/')

            def handler404(self, request, exception):
                return HttpResponsePermanentRedirect('/custom-404/')

            def handler500(self, request):
                return HttpResponsePermanentRedirect('/custom-500/')

        # Create a URLResolver with the mock URLConf
        resolver = URLResolver(RegexPattern(r'^$'), MockURLConf())

        # Check the resolver
        messages = resolver.check()

        # Assert that no warnings or errors are raised
        self.assertEqual(len(messages), 0)

    def test_check_with_missing_error_handler(self):
        """
        Test URLResolver.check() when a custom error handler is missing.
        """
        # Mock URLConf with a missing error handler
        class MockURLConf:
            def handler400(self, request, exception):
                return HttpResponsePermanentRedirect('/custom-400/')

            def handler403(self, request, exception):
                return HttpResponsePermanentRedirect('/custom-403/')

            # handler404 is missing

            def handler500(self, request):
                return HttpResponsePermanentRedirect('/custom-500/')

        # Create a URLResolver with the mock URLConf
        resolver = URLResolver(RegexPattern(r'^$'), MockURLConf())

        # Check the resolver
        messages = resolver.check()

        # Assert that an error is raised for the missing handler
        self.assertEqual(len(messages), 1)
        self.assertEqual(messages[0].id, 'urls.E008')

