def test_itermonomials_complex():
    a, b = symbols('a, b', commutative=False)
    assert set(itermonomials([a, b], 1)) == {1, a, b}
    assert set(itermonomials([a, b], 2)) == {1, a, b, a**2, b**2, a*b, b*a}
    assert set(itermonomials([a, b], 3)) == {1, a, b, a**2, b**2, a**3, b**3, a*b, b*a, a*b**2, b*a**2, a**2*b, b**2*a}
    assert set(itermonomials([a, b], 1, 0)) == {a, b}
    assert set(itermonomials([a, b], 2, 1)) == {a**2, b**2, a*b, b*a}
    assert set(itermonomials([a, b], [1, 2], [0, 1])) == {a, b, b**2}
    assert set(itermonomials([a, b], [1, 2], [1, 2])) == {a**2, b**2, a*b, b*a}
    assert set(itermonomials([a, b], [2, 3], [1, 2])) == {a**2, a*b, b**2, a**2*b, b**2*a}
    assert set(itermonomials([a, b], [2, 3], [1, 3])) == {a**2, a*b, b**3, a**2*b, b**3*a}
    assert set(itermonomials([a, b], [2, 3], [2, 3])) == {a**2, a**2*b, b**2, b**3, a**2*b**2, b**2*a**2}
    assert set(itermonomials([a, b], [2, 3], [2, 2])) == {a**2, a**2*b, b**2, a**2*b**2}
    assert set(itermonomials([a, b], [2, 2], [2, 2])) == {a**2, b**2, a**2*b, b**2*a}
    assert set(itermonomials([a, b], [1, 1], [1, 1])) == {1, a, b, a*b}
    assert set(itermonomials([a, b], [1, 1], [0, 0])) == {1}
    assert set(itermonomials([a, b], [1, 1], [2, 2])) == {a**2, b**2, a*b}
    assert set(itermonomials([a, b], [1, 1], [1, 2])) == {a, b, a*b}
    assert set(itermonomials([a, b], [1, 1], [2, 1])) == {a**2, a*b}
    assert set(itermonomials([a, b], [1, 1], [1, 1])) == {1, a, b, a*b}
