def test_matchnodes_with_package_and_module(testdir):
    """Test that matchnodes correctly handles a package with a module."""
    testdir.makeconftest(
        """
        import pytest
        def pytest_collect_file(path, parent):
            if path.basename == "test_module.py":
                return MyModule(path, parent)
            return parent.collect_file(path, parent)

        class MyModule(pytest.Module):
            def __init__(self, path, parent):
                super().__init__(path, parent)
                self._name = "test_module"

            def collect(self):
                return [pytest.Item("test_function", self)]

        class Item(pytest.Item):
            def __init__(self, name, parent):
                super().__init__(name, parent)

            def runtest(self):
                pass
    """
    )
    package_dir = testdir.mkdir("package")
    module_file = package_dir.join("test_module.py")
    module_file.write("def test_function(): pass")

    result = testdir.runpytest("-v", package_dir)
    result.stdout.fnmatch_lines(
