def test_canonical_variables_complex():
    from sympy import Integral, Symbol
    x, y = Symbol('x'), Symbol('y')
    assert Integral(x, (x, y)).canonical_variables == {x: Symbol('i0')}
    assert Integral(x, (x, y + x)).canonical_variables == {x: Symbol('i0')}
