def test_matches_complex():
    x, y = symbols('x y')
    p = Wild('p')
    q = Wild('q')
    expr = x*y + 1
    assert expr.matches(p*q + 1) == {p: x, q: y}
    assert expr.matches(p*q + 2) is None
    assert expr.matches(p*q) is None
    assert expr.matches(p*q + 1, old=True) == {p: x, q: y}
    assert expr.matches(p*q + 2, old=True) is None
    assert expr.matches(p*q, old=True) is None

    assert (x + y).matches(p + q) == {p: x, q: y}
    assert (x + y).matches(p + q, old=True) == {p: x, q: y}

    assert (x**2 + y).matches(p**2 + q) == {p: x, q: y}
    assert (x**2 + y).matches(p**2 + q, old=True) == {p: x, q: y}

    assert (x**2 + y).matches(p**3 + q) is None
    assert (x**2 + y).matches(p**3 + q, old=True) is None

    assert (x**2 + y).matches(p**2 + q, old=False) == {p: x, q: y}

    assert (x + y).matches(p + q, old=False) == {p: x, q: y}

    assert (x + y).matches(p + q, old=True) == {p: x, q: y}

    assert (x + y).matches(p + q, old=False) == {p: x, q: y}

    assert (x + y).matches(p + q, old=True) == {p: x, q: y}
