import pytest

from sympy.core.basic import Basic, _exec_constructor_postprocessors
from sympy.core.numbers import Integer
from sympy.core.symbol import Symbol
from sympy.core.function import Function

def test_constructor_postprocessors_integer():
    class IntegerWithPostprocessor(Integer):
        _constructor_postprocessor_mapping = {
            Integer: [lambda x: x + 1]
        }

    i = IntegerWithPostprocessor(5)
    assert _exec_constructor_postprocessors(i) == IntegerWithPostprocessor(6)

def test_constructor_postprocessors_symbol():
    class SymbolWithPostprocessor(Symbol):
        _constructor_postprocessor_mapping = {
            Symbol: [lambda x: x.replace('a', 'b')]
        }

    s = SymbolWithPostprocessor('a')
    assert _exec_constructor_postprocessors(s) == SymbolWithPostprocessor('b')

def test_constructor_postprocessors_function():
    class FunctionWithPostprocessor(Function):
        _constructor_postprocessor_mapping = {
            Function: [lambda x: x.replace('f', 'g')]
        }

    f = FunctionWithPostprocessor('f')
    assert _exec_constructor_postprocessors(f) == FunctionWithPostprocessor('g')

def test_constructor_postprocessors_multiple():
    class BasicWithMultiplePostprocessors(Basic):
        _constructor_postprocessor_mapping = {
            Basic: [lambda x: x.args + (1,), lambda x: x.func(*x.args)]
        }

    b = BasicWithMultiplePostprocessors(Symbol('x'))
    result = _exec_constructor_postprocessors(b)
    assert result.args == (Symbol('x'), 1)
    assert result.func == Basic

def test_constructor_postprocessors_no_mapping():
    class BasicNoMapping(Basic):
        pass

    b = BasicNoMapping(Symbol('x'))
    assert _exec_constructor_postprocessors(b) == b

def test_constructor_postprocessors_empty_mapping():
    class BasicEmptyMapping(Basic):
        _constructor_postprocessor_mapping = {}

    b = BasicEmptyMapping(Symbol('x'))
    assert _exec_constructor_postprocessors(b) == b
